    if (
      Services.prefs.getStringPref(
        "mail.openpgp.clear_signature_format"
      ) == "unobtrusive"
    ) {
      sendFlags |= EnigmailConstants.SEND_SIG_UNOBTRUSIVE;
    }
  }
}

